INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '515', 'JohnJohnston', NULL, '<p>I meant blogging via AppleScript was niche. </p><p>What is nice about the <a href="http://rss.chat">rss.chat</a> set up is if I post a link from one tab <a href="http://rss.chat">rss.chat</a> updates the page in another tab without refresh.</p>', 'I meant blogging via AppleScript was niche.

What is nice about the rss.chat set up is if I post a link from one tab rss.chat updates the page in another tab without refresh.', NULL, '514', NULL, NULL, NULL, '2026-08-09T19:14:47Z', '2026-08-09T19:14:47Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '514', 'dave', NULL, 'It''s linkblogging. Not niche, imho.', 'It''s linkblogging. Not niche, imho.', NULL, '513', NULL, NULL, NULL, '2026-08-09T18:57:57Z', '2026-08-09T18:57:57Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '513', 'JohnJohnston', NULL, '<p>I’ve managed to make a small AppleScript that gets the selection from Safari &amp; a link and posts it to <a href="http://RSS.chat">RSS.chat</a>. <a href="https://johnjohnston.info/blog/post-link-quote-to-rss-chat/">Post Link &amp; Quote to RSS.chat</a> Fairly niche.</p>', 'I’ve managed to make a small AppleScript that gets the selection from Safari & a link and posts it to RSS.chat. [Post Link & Quote to RSS.chat](https://johnjohnston.info/blog/post-link-quote-to-rss-chat/) Fairly niche.', NULL, NULL, NULL, NULL, NULL, '2026-08-09T17:21:56Z', '2026-08-09T17:21:56Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '512', 'manton', NULL, 'Cool! I need to update the UI so that it properly shows your server name instead of just "<a href="http://RSS.chat">RSS.chat</a>" everywhere.', 'Cool! I need to update the UI so that it properly shows your server name instead of just "RSS.chat" everywhere.', NULL, '509', NULL, NULL, NULL, '2026-08-08T22:12:56Z', '2026-08-08T22:12:56Z');
