INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '510', 'mistersugar', NULL, 'and, nevermind. I went ahead and clicked it and I see I get to determine the server. Awesome.', 'and, nevermind. I went ahead and clicked it and I see I get to determine the server. Awesome.', NULL, '509', NULL, NULL, NULL, '2026-08-08T16:22:18Z', '2026-08-08T16:22:18Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '509', 'mistersugar', NULL, 'I see the cross-post button in <a href="http://Micro.blog">Micro.blog</a>. It says <a href="http://RSS.chat">RSS.chat</a>. Does that mean it will cross-post here, or can I tell it to cross-post to my <a href="http://RSS.storian.org">RSS.storian.org</a>?', 'I see the cross-post button in Micro.blog. It says RSS.chat. Does that mean it will cross-post here, or can I tell it to cross-post to my RSS.storian.org?', NULL, '503', NULL, NULL, NULL, '2026-08-08T16:21:26Z', '2026-08-08T16:21:26Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '508', 'dave', NULL, '<p>I have this feed.</p><p><a href="https://demo.rss.chat/users/dave/rss.xml">https://demo.rss.chat/users/dave/rss.xml</a></p><p>Hooked up to <a href="http://micro.blog">micro.blog</a> which in turn hooks it up to Bluesky.</p><p>If I write a post there that has a title or is longer than 300 chars, it will use <a href="http://standard.site">standard.site</a>.</p><p>Which I think means it will show up in my timeline as a card, and clicking on a link will take me to the full post inside the "atmosphere" -- they come up with great names in that world! :-)</p><p>I think there''s a feed reader over there, we will find out. </p><p>Once again Manton kicks ass. This is a big door to open.</p><p>I used the <a href="http://demo.rss.chat">demo.rss.chat</a> so other people could contribute without being part of my circle of friends. ;-)</p>', 'I have this feed.

https://demo.rss.chat/users/dave/rss.xml

Hooked up to micro.blog which in turn hooks it up to Bluesky.

If I write a post there that has a title or is longer than 300 chars, it will use standard.site.

Which I think means it will show up in my timeline as a card, and clicking on a link will take me to the full post inside the "atmosphere" -- they come up with great names in that world! :-)

I think there''s a feed reader over there, we will find out.

Once again Manton kicks ass. This is a big door to open.

I used the demo.rss.chat so other people could contribute without being part of my circle of friends. ;-)', NULL, '506', NULL, NULL, NULL, '2026-08-08T14:40:17Z', '2026-08-08T14:40:17Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '507', 'dave', 'Why I want to break through with standard.site folks', '<p>i think breaking the wall betw at proto and the world outside is good for everyone. there is significant work being done there, and people who think like we do, so connecting the two worlds will make a lot more of a difference than say connectiong with threads or even mastodon. they just aren''t listening and don''t care at the companies, but us individual developers have lots of reasons to work with each other, we just tend not to do it. breaking through here will be huge. ​</p><p>note: this was going to be part of a comment on <a href="http://micro.blog">micro.blog</a> but there''s a character limit...</p>', 'i think breaking the wall betw at proto and the world outside is good for everyone. there is significant work being done there, and people who think like we do, so connecting the two worlds will make a lot more of a difference than say connectiong with threads or even mastodon. they just aren''t listening and don''t care at the companies, but us individual developers have lots of reasons to work with each other, we just tend not to do it. breaking through here will be huge. ​

note: this was going to be part of a comment on [micro.blog](http://micro.blog) but there''s a character limit...', NULL, '506', NULL, NULL, NULL, '2026-08-08T14:20:38Z', '2026-08-08T14:20:38Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '506', 'dave', 'Connecting RSS and AT Proto', '<p><i>We''re going to make this happen.</i></p><p>I think it''s really important for us to connect with developers who make writing tools for AT Proto. We should be part of the same community, I feel that very strongly, so I am seeking new ways to make that happen via RSS.</p><p>I noticed they had a feed in Leaflet, one of the editors, so I created an account entered a few posts, and then looked to see what was there. I then wrote the developer privately, to ask if he would welcome a review, and he did. I made the time this morning to put together the review.</p><p><a href="https://github.com/scripting/Scripting-News/issues/359">https://github.com/scripting/Scripting-News/issues/359</a></p><p>In the other direction, I''ve been asking everyone I know who could possibly help, how to go in the other direction, have my RSS feed show up in AT Proto as whatever it is that makes new posts from people in that world. </p><p>People keep telling me it''s not like RSS, and I can''t imagine how it could be anything other than RSS. So the answer was, until yesterday -- no -- you can''t do it or we don''t know how to do it. Except I asked the question again, on <a href="http://micro.blog">micro.blog</a> and <a href="https://micro.blog/manton/95380703">Manton says</a> they have the feature. Of course he does. Manton covers every freaking protocol ever invented.</p>', '_We''re going to make this happen._

I think it''s really important for us to connect with developers who make writing tools for AT Proto. We should be part of the same community, I feel that very strongly, so I am seeking new ways to make that happen via RSS.

I noticed they had a feed in Leaflet, one of the editors, so I created an account entered a few posts, and then looked to see what was there. I then wrote the developer privately, to ask if he would welcome a review, and he did. I made the time this morning to put together the review.

[https://github.com/scripting/Scripting-News/issues/359](https://github.com/scripting/Scripting-News/issues/359)

In the other direction, I''ve been asking everyone I know who could possibly help, how to go in the other direction, have my RSS feed show up in AT Proto as whatever it is that makes new posts from people in that world.

People keep telling me it''s not like RSS, and I can''t imagine how it could be anything other than RSS. So the answer was, until yesterday -- no -- you can''t do it or we don''t know how to do it. Except I asked the question again, on [micro.blog](http://micro.blog) and [Manton says](https://micro.blog/manton/95380703) they have the feature. Of course he does. Manton covers every freaking protocol ever invented.', NULL, NULL, NULL, NULL, NULL, '2026-08-08T14:13:30Z', '2026-08-08T14:13:30Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '505', 'dave', 'Losing my shit about first day’s work', 'It’s starting to work, we have a table editor odb browser, and can edit, update and run scripts. The runtime lives in the cloud, the client is an electron app. I had to call it a day early because my poor human mind is having trouble keeping up with the new reality. Do you know how long I’ve wanted this? Btw the builtin webserver works. I’ve mastered Node, but frontier has so more factored, the model is much simpler iirc.', 'It’s starting to work, we have a table editor odb browser, and can edit, update and run scripts. The runtime lives in the cloud, the client is an electron app. I had to call it a day early because my poor human mind is having trouble keeping up with the new reality. Do you know how long I’ve wanted this? Btw the builtin webserver works. I’ve mastered Node, but frontier has so more factored, the model is much simpler iirc.', NULL, '501', NULL, NULL, NULL, '2026-08-07T19:58:19Z', '2026-08-07T19:58:19Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '504', 'dave', NULL, 'I love it. Thank you for being part of this project. ❤️', 'I love it. Thank you for being part of this project. ❤️', NULL, '503', NULL, NULL, NULL, '2026-08-07T19:39:24Z', '2026-08-07T19:39:24Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '503', 'manton', NULL, '<p>I rolled out basic cross-posting from <a href="http://Micro.blog">Micro.blog</a> to <a href="http://RSS.chat">RSS.chat</a> this week. Here''s a screenshot of what the menu looks like. Still have some improvements I can make later.</p><p><img src="https://rss.chat/media/11" /></p>', 'I rolled out basic cross-posting from Micro.blog to RSS.chat this week. Here''s a screenshot of what the menu looks like. Still have some improvements I can make later.

![](https://rss.chat/media/11)', NULL, NULL, NULL, NULL, NULL, '2026-08-07T16:59:56Z', '2026-08-07T16:59:56Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '502', 'dave', NULL, 'The credit really goes to Andrew Shell who made it really easy for us to hook in, then we figured out the rest of it. We''re using the header, not adding anything to our feeds.', 'The credit really goes to Andrew Shell who made it really easy for us to hook in, then we figured out the rest of it. We''re using the header, not adding anything to our feeds.', NULL, '499', NULL, NULL, NULL, '2026-08-07T16:32:05Z', '2026-08-07T16:32:05Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '501', 'dave', NULL, 'Update -- I didn''t like the idea of turning Drummer into a programming environment so instead I asked Claude to give its version of Frontier a user interface. Parts of it are starting to work one hour later. Using Electron, Concord (the outliner I keep reusing) and all the other stuff. If it all works I will be able to run Frontier on my desktop. Also the ODB is a SQL database.', 'Update -- I didn''t like the idea of turning Drummer into a programming environment so instead I asked Claude to give its version of Frontier a user interface. Parts of it are starting to work one hour later. Using Electron, Concord (the outliner I keep reusing) and all the other stuff. If it all works I will be able to run Frontier on my desktop. Also the ODB is a SQL database.', NULL, NULL, NULL, NULL, NULL, '2026-08-07T16:30:22Z', '2026-08-07T16:30:22Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '500', 'manton', NULL, 'I''m working on posting from <a href="http://Micro.blog">Micro.blog</a> to <a href="http://RSS.chat">RSS.chat</a> today, using the API. For completeness, I think support for the Micropub posting API or even MetaWeblog would be good. Then some existing clients could post to <a href="http://RSS.chat">RSS.chat</a> with minimal or no changes.', 'I''m working on posting from Micro.blog to RSS.chat today, using the API. For completeness, I think support for the Micropub posting API or even MetaWeblog would be good. Then some existing clients could post to RSS.chat with minimal or no changes.', NULL, NULL, NULL, NULL, NULL, '2026-08-06T16:12:27Z', '2026-08-06T16:12:27Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '499', 'manton', NULL, 'Great to see WebSub support too. 👍', 'Great to see WebSub support too. 👍', NULL, '497', NULL, NULL, NULL, '2026-08-06T15:44:04Z', '2026-08-06T15:44:04Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '498', 'andrewshell', NULL, 'My initial tests show it works as expected!', 'My initial tests show it works as expected!', NULL, '497', NULL, NULL, NULL, '2026-08-05T23:37:51Z', '2026-08-05T23:37:51Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '497', 'dave', 'WebSub support in RSS.chat', '<p>Previously we were only able to notify via rssCloud. </p><p>Now we also support WebSub because there are also a fair number of feed readers that only use WebSub. </p><p>We''re using Andrew Shell''s <a href="http://rsscloud.io">rsscloud.io</a> as <a href="https://andrewshell.org/2026/07/rsscloud-server-4-0-now-supports-websub-notifications/">our WebSub hub</a>, as we have for a long time with rssCloud. </p><p>Andrew please help us figure out if this is working correctly.</p><p>The source is <a href="https://github.com/scripting/rss.chat/blob/main/server/code/rssnetwork.js">in the repo</a>, along with a <a href="https://github.com/scripting/rss.chat/blob/main/server/code/worknotes.md#8526-302-pm-et-by-cc">worknote</a>.</p>', 'Previously we were only able to notify via rssCloud.

Now we also support WebSub because there are also a fair number of feed readers that only use WebSub.

We''re using Andrew Shell''s [rsscloud.io](http://rsscloud.io) as [our WebSub hub](https://andrewshell.org/2026/07/rsscloud-server-4-0-now-supports-websub-notifications/), as we have for a long time with rssCloud.

Andrew please help us figure out if this is working correctly.

The source is [in the repo](https://github.com/scripting/rss.chat/blob/main/server/code/rssnetwork.js), along with a [worknote](https://github.com/scripting/rss.chat/blob/main/server/code/worknotes.md#8526-302-pm-et-by-cc).', NULL, NULL, NULL, NULL, NULL, '2026-08-05T19:13:14Z', '2026-08-05T19:13:14Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '496', 'andrewshell', NULL, 'Added a river to I ♥ RSS: <a href="https://iheartrss.com/river">https://iheartrss.com/river</a>', 'Added a river to I ♥ RSS: https://iheartrss.com/river', NULL, NULL, NULL, NULL, NULL, '2026-08-05T15:55:26Z', '2026-08-05T15:55:26Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '495', 'dave', NULL, '<p>Andrew wrote a post about the fantastic FreshRSS.</p><p><a href="https://andrewshell.org/2026/08/enhancing-freshrss-with-rsscloud-support/">https://andrewshell.org/2026/08/enhancing-freshrss-with-rsscloud-support/</a></p><p>Claude, must read.</p>', 'Andrew wrote a post about the fantastic FreshRSS.

[https://andrewshell.org/2026/08/enhancing-freshrss-with-rsscloud-support/](https://andrewshell.org/2026/08/enhancing-freshrss-with-rsscloud-support/)

Claude, must read.', NULL, NULL, NULL, NULL, NULL, '2026-08-03T19:35:50Z', '2026-08-03T19:35:50Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '494', 'dave', NULL, 'It certainly hasn’t been deployed on <a href="http://feedland.com">feedland.com</a> yet, and we should update the npm stuff, I think I wrote change notes, esp in the issues section on feedlandinstall. That’s the best place to ask for help.', 'It certainly hasn’t been deployed on feedland.com yet, and we should update the npm stuff, I think I wrote change notes, esp in the issues section on feedlandinstall. That’s the best place to ask for help.', NULL, '493', NULL, NULL, NULL, '2026-08-03T19:06:23Z', '2026-08-03T19:06:23Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '493', 'andrewshell', NULL, 'Hey Dave! I was talking to a user, and he''s having issues with feedland (probably <a href="http://feedland.com">feedland.com</a>) not subscribing to his rssCloud via https when his cloud specified port 443. I know you fixed this on <a href="http://feedland.social">feedland.social</a> back in May, but it doesn''t look like it made it to GitHub, npm, or <a href="http://feedland.com">feedland.com</a>. I suggested he just use my rssCloud server instead, but I''m wondering if you have plans to get this update pushed out? Maybe at the same time as the support for rssCloud in OPML files?', 'Hey Dave! I was talking to a user, and he''s having issues with feedland (probably [feedland.com](http://feedland.com)) not subscribing to his rssCloud via https when his cloud specified port 443. I know you fixed this on [feedland.social](http://feedland.social) back in May, but it doesn''t look like it made it to GitHub, npm, or [feedland.com](http://feedland.com). I suggested he just use my rssCloud server instead, but I''m wondering if you have plans to get this update pushed out? Maybe at the same time as the support for rssCloud in OPML files?', NULL, NULL, NULL, NULL, NULL, '2026-08-03T18:54:13Z', '2026-08-03T18:54:13Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '492', 'JohnJohnston', NULL, '<p>Thanks Dave</p><p><br /></p><p><img src="https://rss.chat/media/10" /></p><p>I went for an orange dogcow</p>', 'Thanks Dave



![](https://rss.chat/media/10)

I went for an orange dogcow', NULL, '478', NULL, NULL, NULL, '2026-08-02T19:32:14Z', '2026-08-02T19:32:14Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '491', 'dave', NULL, 'Ahh I misunderstood. Now I get it.', 'Ahh I misunderstood. Now I get it.', NULL, '486', NULL, NULL, NULL, '2026-08-02T18:53:28Z', '2026-08-02T18:53:28Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '490', 'dave', NULL, 'There''s no redirect involved, we serve the HTML shell of the app, including the full &lt;head&gt; section straight from the <a href="http://rss.chat">rss.chat</a> server. You should get all our meta data when you just do an HTTP read of <a href="https://rss.chat/">https://rss.chat/</a>.', 'There''s no redirect involved, we serve the HTML shell of the app, including the full <head> section straight from the rss.chat server. You should get all our meta data when you just do an HTTP read of https://rss.chat/.', NULL, '487', NULL, NULL, NULL, '2026-08-02T18:53:01Z', '2026-08-02T18:53:01Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '489', 'dave', NULL, 'Very nicely done Don! ;-)', 'Very nicely done Don! ;-)', NULL, '488', NULL, NULL, NULL, '2026-08-02T18:51:44Z', '2026-08-02T18:51:44Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '488', 'donpark', NULL, '<p>I''ve merged my brain into main branch of my fork and renamed the fork as <strong>rss.voice</strong> to give it a distinct, ur, <em>voice</em>. So the new link is: <a href="https://github.com/donpark/rss.voice">https://github.com/donpark/rss.voice</a></p>', 'I''ve merged my brain into main branch of my fork and renamed the fork as **rss.voice** to give it a distinct, ur, _voice_. So the new link is: https://github.com/donpark/rss.voice', NULL, '485', NULL, NULL, NULL, '2026-08-02T18:45:40Z', '2026-08-02T18:45:40Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '487', 'andrewshell', NULL, 'I pushed out a fix that if we can''t find the link in the html source, we fetch it via a browser. Takes a second or two longer, but it looks like <a href="http://rss.chat">rss.chat</a> should work now.', 'I pushed out a fix that if we can''t find the link in the html source, we fetch it via a browser. Takes a second or two longer, but it looks like rss.chat should work now.', NULL, '484', NULL, NULL, NULL, '2026-08-02T18:41:16Z', '2026-08-02T18:41:16Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '486', 'andrewshell', NULL, 'The reason it''s failing is that the link to <a href="http://iheartrss.com">iheartrss.com</a> isn''t in your HTML source (it''s only in a post which is pulled in via JavaScript at runtime). <br /><br />The easiest fix, if you''re willing, would probably be adding the link in your docs menu, maybe under RSS &amp; OPML, because that''s rendered server-side. <br /><br />Otherwise, I have a fix to use a Cloudflare API to fetch the page with a browser, which works, but once your post leaves the homepage, the validator will remove you from the list.', 'The reason it''s failing is that the link to iheartrss.com isn''t in your HTML source (it''s only in a post which is pulled in via JavaScript at runtime).

The easiest fix, if you''re willing, would probably be adding the link in your docs menu, maybe under RSS & OPML, because that''s rendered server-side.

Otherwise, I have a fix to use a Cloudflare API to fetch the page with a browser, which works, but once your post leaves the homepage, the validator will remove you from the list.', NULL, '484', NULL, NULL, NULL, '2026-08-02T17:38:43Z', '2026-08-02T17:38:43Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '485', 'donpark', NULL, '<p>That''s fine. I consider voice posting to be a core feature that grants <a href="http://rss.chat">rss.chat</a> a fluid multiuser async voice chat experience. You should try it out if you haven''t because it feels different than how one might imagine. A strong whiff of magic sauce.</p>

<p>I''ve closed the PR but, if anyone wants to try it, it''s in the "voice-post" branch of <a href="https://github.com/donpark/rss.chat">my fork</a>.</p>', 'That''s fine. I consider voice posting to be a core feature that grants [rss.chat](http://rss.chat) a fluid multiuser async voice chat experience. You should try it out if you haven''t because it feels different than how one might imagine. A strong whiff of magic sauce.

I''ve closed the PR but, if anyone wants to try it, it''s in the "voice-post" branch of [my fork](https://github.com/donpark/rss.chat).', NULL, '479', NULL, NULL, NULL, '2026-08-02T17:19:20Z', '2026-08-02T17:19:20Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '484', 'dave', NULL, 'not clear exactly what''s not working. will wait for details.', 'not clear exactly what''s not working. will wait for details.', NULL, '483', NULL, NULL, NULL, '2026-08-02T16:45:53Z', '2026-08-02T16:45:53Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '483', 'andrewshell', NULL, 'It looks like the JavaScript-rendered page content is blocking right now, but I''m having Claude suggest some fixes. :-)', 'It looks like the JavaScript-rendered page content is blocking right now, but I''m having Claude suggest some fixes. :-)', NULL, '482', NULL, NULL, NULL, '2026-08-02T16:32:34Z', '2026-08-02T16:32:34Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '482', 'dave', NULL, 'I just fixed this issue, but I have to post something to cause the feeds to rebuild.', 'I just fixed this issue, but I have to post something to cause the feeds to rebuild.', NULL, '481', NULL, NULL, NULL, '2026-08-02T16:18:23Z', '2026-08-02T16:18:23Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '481', 'dave', NULL, '<p>Absolutely!</p><p>I think you''re serving a great purpose, you just made my site better. Haven''t made the change yet.</p>', 'Absolutely!

I think you''re serving a great purpose, you just made my site better. Haven''t made the change yet.', NULL, '480', NULL, NULL, NULL, '2026-08-02T15:55:15Z', '2026-08-02T15:55:15Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '480', 'andrewshell', NULL, 'Do you think this makes sense? My reasoning was that the channel link is what the blogroll will link to so that''s where the backlink should be.', 'Do you think this makes sense? My reasoning was that the channel link is what the blogroll will link to so that''s where the backlink should be.', NULL, '474', NULL, NULL, NULL, '2026-08-02T15:49:38Z', '2026-08-02T15:49:38Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '479', 'dave', NULL, '<p>Don, thanks for this idea, we can''t use it here at this time, for this reason:</p><p>I want to keep this site as the basis for what we''re doing overall, and while voice in a conference system like this makes a ton of sense, it isn''t a core feature. </p><p>But there seem to be a few forks of <a href="http://RSS.chat">RSS.chat</a> out there, and they''re adding features at a pretty rapid rate. Why don''t you try this idea out with one of them? Then we could see what people do with it, without changing what the reference version does.</p>', 'Don, thanks for this idea, we can''t use it here at this time, for this reason:

I want to keep this site as the basis for what we''re doing overall, and while voice in a conference system like this makes a ton of sense, it isn''t a core feature.

But there seem to be a few forks of RSS.chat out there, and they''re adding features at a pretty rapid rate. Why don''t you try this idea out with one of them? Then we could see what people do with it, without changing what the reference version does.', NULL, '476', NULL, NULL, NULL, '2026-08-02T15:40:02Z', '2026-08-02T15:40:02Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '478', 'dave', NULL, '<p>You can chage the favicon. </p><p>In config.json add this:</p><p>"urlFavicon": "<a href="https://url-to-your-favicon">https://url-to-your-favicon</a>"</p><p>Then restart the server. If you look carefully you can see that I changed the favicon for this site. </p>', 'You can chage the favicon.

In config.json add this:

"urlFavicon": "https://url-to-your-favicon"

Then restart the server. If you look carefully you can see that I changed the favicon for this site.', NULL, '477', NULL, NULL, NULL, '2026-08-02T15:36:00Z', '2026-08-02T15:36:00Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '477', 'JohnJohnston', 'Too many dogcows', '<p>Trivial thought: Running my own rsschat the favicon is the same as <a href="http://rss.chat">rss.chat</a> &amp; <a href="http://demo.rss.chat">demo.rss.chat</a>.  The other day I had drummer and scripting open in the same window too. I often have enough tabs open that I can''t see the titles just icons.  </p><p>Is there a way to set the favicon for a server you are running?</p>', 'Trivial thought: Running my own rsschat the favicon is the same as rss.chat & demo.rss.chat.  The other day I had drummer and scripting open in the same window too. I often have enough tabs open that I can''t see the titles just icons.

Is there a way to set the favicon for a server you are running?', NULL, NULL, NULL, NULL, NULL, '2026-08-02T09:04:39Z', '2026-08-02T09:04:39Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '476', 'donpark', NULL, '@dave, I''ve created a <a href="https://github.com/scripting/rss.chat/pull/21">PR</a> that implements voice message posting. Maximum duration is 4 minutes which should fit under 2MB limit.<br /><br /><p>The PR adds browser voice recording with MediaRecorder, optional live transcription, Mediabunny MP3 conversion, cancellable media cleanup, enclosure-backed audio players, and nightly orphan collection.</p><p>Also include a repeatable localhost development setup with SQLite, CORS-aware client serving, local config bootstrap, and documented npm 12 native-build recovery.<br /><br />PS: I am pretty sure this PR is not a hallucination.<br />PPS: I think you asked me for something like this 6yrs ago. Better late than never.<br />PPPS: Quality of transcription is horseshit which is why I typical used a embedded model but I figured you wouldn''t like <a href="http://rss.chat">rss.chat</a> loading models weighing hundreds of MBs.</p><a href="https://private-user-images.githubusercontent.com/127594/630214509-605d5a77-c9d0-49b8-8393-32bb915ce575.png?jwt=eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiJ9.eyJpc3MiOiJnaXRodWIuY29tIiwiYXVkIjoicmF3LmdpdGh1YnVzZXJjb250ZW50LmNvbSIsImtleSI6ImtleTUiLCJleHAiOjE3ODU2NTA4NzksIm5iZiI6MTc4NTY1MDU3OSwicGF0aCI6Ii8xMjc1OTQvNjMwMjE0NTA5LTYwNWQ1YTc3LWM5ZDAtNDliOC04MzkzLTMyYmI5MTVjZTU3NS5wbmc_._u-jpMCO6cxmQtkX95gpl_l5mhDM2AsVuK40E1RrmQ0"></a>', '@dave, I''ve created a [PR](https://github.com/scripting/rss.chat/pull/21) that implements voice message posting. Maximum duration is 4 minutes which should fit under 2MB limit.


The PR adds browser voice recording with MediaRecorder, optional live transcription, Mediabunny MP3 conversion, cancellable media cleanup, enclosure-backed audio players, and nightly orphan collection.

Also include a repeatable localhost development setup with SQLite, CORS-aware client serving, local config bootstrap, and documented npm 12 native-build recovery.

PS: I am pretty sure this PR is not a hallucination.
PPS: I think you asked me for something like this 6yrs ago. Better late than never.
PPPS: Quality of transcription is horseshit which is why I typical used a embedded model but I figured you wouldn''t like [rss.chat](http://rss.chat) loading models weighing hundreds of MBs.

[](https://private-user-images.githubusercontent.com/127594/630214509-605d5a77-c9d0-49b8-8393-32bb915ce575.png?jwt=eyJ0eXAiOiJKV1QiLCJhbGciOiJIUzI1NiJ9.eyJpc3MiOiJnaXRodWIuY29tIiwiYXVkIjoicmF3LmdpdGh1YnVzZXJjb250ZW50LmNvbSIsImtleSI6ImtleTUiLCJleHAiOjE3ODU2NTA4NzksIm5iZiI6MTc4NTY1MDU3OSwicGF0aCI6Ii8xMjc1OTQvNjMwMjE0NTA5LTYwNWQ1YTc3LWM5ZDAtNDliOC04MzkzLTMyYmI5MTVjZTU3NS5wbmc_._u-jpMCO6cxmQtkX95gpl_l5mhDM2AsVuK40E1RrmQ0)', NULL, NULL, NULL, NULL, NULL, '2026-08-02T06:06:51Z', '2026-08-02T06:06:51Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '475', 'donpark', NULL, 'Nevermind. Looks like I hallucinated.', 'Nevermind. Looks like I hallucinated.', NULL, '473', NULL, NULL, NULL, '2026-08-02T02:32:17Z', '2026-08-02T02:32:17Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '474', 'dave', NULL, '<p>Signing us up for <a href="https://iheartrss.com/">https://iheartrss.com/</a>. </p><p>Must link to site! 🤠</p><p>It’s very clever and a bit of a validator which is great.</p><p>I registered as <a href="https://rss.chat/">https://rss.chat/</a> but the channel-level link element points to <a href="http://rss.chat/">http://rss.chat/</a>.</p><p>No good, you don’t live RSS sufficiently it reports. Try again tomorrow, I say.</p>', 'Signing us up for [https://iheartrss.com/](https://iheartrss.com/).

Must link to site! 🤠

It’s very clever and a bit of a validator which is great.

I registered as [https://rss.chat/](https://rss.chat/) but the channel-level link element points to [http://rss.chat/](http://rss.chat/).

No good, you don’t live RSS sufficiently it reports. Try again tomorrow, I say.', NULL, NULL, NULL, NULL, NULL, '2026-08-02T01:53:39Z', '2026-08-02T01:53:39Z');
