INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '463', 'dave', 'Soft networks', 'I want soft networks that people can configure themselves  that just pop up you do your thing and they pop right off.

There’s so much overhead in creating an identity on a service like bluesky but what about just for the little things.

We can do that privately, but what if it isn’t private.', 'I want soft networks that people can configure themselves that just pop up you do your thing and they pop right off. There’s so much overhead in creating an identity on a service like bluesky but what about just for the little things. We can do that privately, but what if it isn’t private.', NULL, NULL, NULL, NULL, NULL, '2026-08-01T17:16:34Z', '2026-08-01T17:16:34Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '462', 'dave', NULL, '<p>This could be a really great service, sort of a real world validator. Track how is RSS being supported by readers, not just the content side.</p><p>I did something like this when writing the 0.91 spec, we had pretty much the whole world on <a href="http://my.userland.com">my.userland.com</a>, I wanted to see if feeds were respecting the numeric limits on size in the Netscape spec.</p>', 'This could be a really great service, sort of a real world validator. Track how is RSS being supported by readers, not just the content side.

I did something like this when writing the 0.91 spec, we had pretty much the whole world on [my.userland.com](http://my.userland.com), I wanted to see if feeds were respecting the numeric limits on size in the Netscape spec.', NULL, '460', NULL, NULL, NULL, '2026-08-01T17:15:11Z', '2026-08-01T17:15:11Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '461', 'JohnJohnston', NULL, '<p>Hello Matthias, thanks for the plugin (and the others webmentions etc).</p><p> I am seeing that direct replies on  <a href="http://rss.chat">rss.chat</a> are being pulled back to <a href="https://johnjohnston.info/blog/wordpress-rss-chat-update/">my post</a>, not replies to replies. This is the expected behaviour?</p>', 'Hello Matthias, thanks for the plugin (and the others webmentions etc).

I am seeing that direct replies on  rss.chat are being pulled back to [my post](https://johnjohnston.info/blog/wordpress-rss-chat-update/), not replies to replies. This is the expected behaviour?', NULL, '456', NULL, NULL, NULL, '2026-08-01T17:09:13Z', '2026-08-01T17:09:13Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '460', 'andrewshell', NULL, 'So far, I''ve tested FreshRSS, Feedbin, Feedly, and Inoreader. <br /><br />FreshRSS is fast and handles all variants. Inoreader also seems to handle all variants, although yesterday it seemed to be delayed, but today it came back fast. <br /><br />Feedly didn''t seem to respond to anything, but it might just be slow/backlogged.<br /><br />Feedbin seems to be a naive parser because it only worked with the atom:link elements, not the websub:link variant.<br /><br />I tried testing <a href="http://micro.blog">micro.blog</a> but so far it still says "Posts for this user are still being downloaded." for all variants.', 'So far, I''ve tested FreshRSS, Feedbin, Feedly, and Inoreader.

FreshRSS is fast and handles all variants. Inoreader also seems to handle all variants, although yesterday it seemed to be delayed, but today it came back fast.

Feedly didn''t seem to respond to anything, but it might just be slow/backlogged.

Feedbin seems to be a naive parser because it only worked with the atom:link elements, not the websub:link variant.

I tried testing micro.blog but so far it still says "Posts for this user are still being downloaded." for all variants.', NULL, '448', NULL, NULL, NULL, '2026-08-01T14:49:18Z', '2026-08-01T14:49:18Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '459', 'dave', NULL, '<p>The Settings command is way over on the right, in the "System" menu.</p><p>Once there you can enter your name, and a description of who you are. </p><p>If you haven''t been there yet, help everyone else know who you are.</p><p><img src="https://rss.chat/media/9" /></p>', 'The Settings command is way over on the right, in the "System" menu.

Once there you can enter your name, and a description of who you are.

If you haven''t been there yet, help everyone else know who you are.

Uploading image…', NULL, NULL, NULL, NULL, NULL, '2026-08-01T12:45:56Z', '2026-08-01T12:45:56Z');
