INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '455', 'JohnJohnston', 'rss.chat update', '<p>I’ve updated my rss chat server on my Raspberry Pi: <a href="https://rsschat.johnj.info/">John’s Pi chat</a>. A new feature is adding a menu of commands to the menubar.  I followed the <a href="https://github.com/scripting/rss.chat/blob/main/client/code/worknotes.md#73126-930-am-et-by-cc">instructions</a>. Just for fun I decided to edit the example in drummer rather than locally. This lead to a mistake where I used the link button to add a link 🔗, rather than a url attribute, with the suitcase button . Anyway easy to fix. I made <a href="https://drummer.land/johnjohnston@mac.com/jjrsschat.opml">the outline</a> public and used that in the config. Using Drummer for the first time in a long while reminded me of the scripts menu which, in my mind links to  <em>today a type="link" node opens its url in a new tab; other types get their behaviours later</em>.  Other types sounds interesting.</p>', 'I’ve updated my rss chat server on my Raspberry Pi: [John’s Pi chat](https://rsschat.johnj.info/). A new feature is adding a menu of commands to the menubar. I followed the [instructions](https://github.com/scripting/rss.chat/blob/main/client/code/worknotes.md#73126-930-am-et-by-cc). Just for fun I decided to edit the example in drummer rather than locally. This lead to a mistake where I used the link button to add a link 🔗, rather than a url attribute, with the suitcase button . Anyway easy to fix. I made [the outline](https://drummer.land/johnjohnston@mac.com/jjrsschat.opml) public and used that in the config. Using Drummer for the first time in a long while reminded me of the scripts menu which, in my mind links to  _today a `type="link"` node opens its url in a new tab; other types get their behaviours later_.  Other types sounds interesting.', NULL, NULL, NULL, NULL, NULL, '2026-08-01T11:07:11Z', '2026-08-01T11:07:11Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '454', 'JohnJohnston', NULL, '<p>Posted from my blog: <a href="https://johnjohnston.info/blog/wordpress-rss-chat-update/">WordPress RSS Chat Update</a>, where your reply has already been come through. This one posted form <a href="http://rss.chat">rss.chat</a>.</p>', 'Posted from my blog: [WordPress RSS Chat Update](https://johnjohnston.info/blog/wordpress-rss-chat-update/), where your reply has already been come through. This one posted form rss.chat.', NULL, '452', NULL, NULL, NULL, '2026-08-01T09:52:06Z', '2026-08-01T09:52:06Z');
