INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '451', 'JohnJohnston', 'WordPress RSS Chat Update', '<p>Just updated<a href="https://github.com/pfefferle/wordpress-rss-chat"> wordpress-rss-chat</a> after a <a href="https://github.com/pfefferle/wordpress-rss-chat/issues/1">couple of fixes</a>.</p>', 'Just updated [wordpress-rss-chat](https://github.com/pfefferle/wordpress-rss-chat) after a [couple of fixes](https://github.com/pfefferle/wordpress-rss-chat/issues/1).', NULL, NULL, NULL, NULL, NULL, '2026-08-01T09:03:33Z', '2026-08-01T09:03:33Z');
