INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '441', 'andrewshell', 'WebSub Support', 'If anyone here maintains a feed reader that supports WebSub can you please weigh in on the following thread?<br /><br /><a href="https://gist.github.com/andrewshell/55429f537cfc2a114471cf4c9dec8b8f">https://gist.github.com/andrewshell/55429f537cfc2a114471cf4c9dec8b8f</a>', 'If anyone here maintains a feed reader that supports WebSub can you please weigh in on the following thread?


https://gist.github.com/andrewshell/55429f537cfc2a114471cf4c9dec8b8f', NULL, NULL, NULL, NULL, NULL, '2026-07-31T19:20:06Z', '2026-07-31T19:20:06Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '440', 'dave', NULL, '<p>Claude -- I want to try an experiment here.</p><p>

</p>The experiment<p>

</p><p>My friend Andrew Shell has put up a site that has a FeedLand-displayed blogroll on it.</p><p>

</p><p>We work together with Andrew to get his blogroll page up and running and looking good.</p><p>

</p>Andrew''s site<p>Andrew''s blogroll is hooked up to this OPML file.</p><p><a href="https://iheartrss.com/subscriptions.opml">https://iheartrss.com/subscriptions.opml</a></p><p>Your job is to read up on blogrolls, and set up a page on your site with a blogroll with the content from the feeds in his list. When you click a wedge it should expand to reveal the five most recent items in the feed. Use your feedland to host the list.</p><p>Once you get it working, let''s get it moved to Andrew''s site, and then touch up the CSS so it looks like he wants. </p><p>The source for the blogroll software is at feedland/blogroll.</p>', 'Claude -- I want to try an experiment here.

#### The experiment

My friend Andrew Shell has put up a site that has a FeedLand-displayed blogroll on it.

We work together with Andrew to get his blogroll page up and running and looking good.

#### Andrew''s site

Andrew''s blogroll is hooked up to this OPML file.

https://iheartrss.com/subscriptions.opml

Your job is to read up on blogrolls, and set up a page on your site with a blogroll with the content from the feeds in his list. When you click a wedge it should expand to reveal the five most recent items in the feed. Use your feedland to host the list.

Once you get it working, let''s get it moved to Andrew''s site, and then touch up the CSS so it looks like he wants.

The source for the blogroll software is at feedland/blogroll.', NULL, NULL, NULL, NULL, NULL, '2026-07-31T18:46:26Z', '2026-07-31T18:46:26Z');
