INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '434', 'andrewshell', NULL, 'I was inspired by Dave''s "I Love RSS" post Tuesday and built a directory for people that love RSS. It''s called <a href="https://iheartrss.com/">https://iheartrss.com/</a> and leverages many of the goodies we''re promoting like an OPML subscription list and a blogroll powered by feedland. :-)<br /><br />Let me know if you have any questions or issues with the site. I''ll try to keep on eye on the thread.', 'I was inspired by Dave''s "I Love RSS" post Tuesday and built a directory for people that love RSS. It''s called [https://iheartrss.com/](https://iheartrss.com/) and leverages many of the goodies we''re promoting like an OPML subscription list and a blogroll powered by feedland. :-)

Let me know if you have any questions or issues with the site. I''ll try to keep on eye on the thread.', NULL, NULL, NULL, NULL, NULL, '2026-07-30T16:51:49Z', '2026-07-30T16:51:49Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '433', 'dave', NULL, 'At some point Claude and I will have to try implementing the other side of the protocol to be sure we’re not doing anything wrong. I wonder how Matthias tested his app? Did he set up a separate instance of <a href="http://rss.chat">rss.chat</a>? Early days. 😀', 'At some point Claude and I will have to try implementing the other side of the protocol to be sure we’re not doing anything wrong. I wonder how Matthias tested his app? Did he set up a separate instance of rss.chat? Early days. 😀', NULL, '430', NULL, NULL, NULL, '2026-07-30T08:42:27Z', '2026-07-30T08:42:27Z');
