INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '428', 'JohnJohnston', NULL, '<p><a href="https://micro.blog/thebigbabooski">@thebigbabooski</a> Thanks, I think there is some untangling to do between, my WordPress - <a href="http://micro.blog">micro.blog</a> &amp; <a href="http://rss.chat">rss.chat</a> I <em>think</em> <a href="http://rss.chat">@rss.chat</a> on <a href="http://micro.blog">micro.blog</a> might be a fire hose from the <a href="http://rss.chat">rss.chat</a> feed? I am posting this in   <a href="http://micro.blog">micro.blog</a> web, wondering where it will turn up!</p>', '[@thebigbabooski](https://micro.blog/thebigbabooski) Thanks, I think there is some untangling to do between, my WordPress - micro.blog & rss.chat I _think_ [@rss.chat](http://rss.chat) on micro.blog might be a fire hose from the rss.chat feed? I am posting this in micro.blog web, wondering where it will turn up!', NULL, '24', NULL, NULL, NULL, '2026-07-29T12:16:17Z', '2026-07-29T12:16:17Z');
