INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '422', 'jsavin', NULL, 'I had the pleasure of meeting <a href="https://x.com/natebjones">@NateBJones</a> this evening at an event here in Seattle. If you''re following people in the AI strategy space, he''s a good one: <a href="https://www.youtube.com/@NateBJones">YouTube</a>, <a href="https://natesnewsletter.substack.com/">Substack</a>. He''s been an important influence on how I use agent harnesses like Claude Code and Codex, and is well worth a follow.', 'I had the pleasure of meeting [@NateBJones](https://x.com/natebjones) this evening at an event here in Seattle. If you''re following people in the AI strategy space, he''s a good one: [YouTube](https://www.youtube.com/@NateBJones), [Substack](https://natesnewsletter.substack.com/). He''s been an important influence on how I use agent harnesses like Claude Code and Codex, and is well worth a follow.', NULL, NULL, NULL, NULL, NULL, '2026-07-28T07:16:01Z', '2026-07-28T07:16:01Z');
INSERT OR IGNORE INTO posts (tenant_id, id, author, title, description, markdowntext, link, in_reply_to, enclosure_url, enclosure_type, enclosure_length, published_at, updated_at) VALUES ('default', '421', 'mistersugar', NULL, '<p>Here to report that I fairly easily installed an <a href="http://RSS.chat">RSS.chat</a> server on my webhost at <a href="https://rss.storian.org">RSS.storian.org</a> (whitelisted to me only for now). I wrote a first post and immediately subscribed to my feed in my installation of Feedland (Zuiker tab in my <a href="https://news.mistersugar.com">News Product</a>). Will stop here for the night, satisfied.</p>', 'Here to report that I fairly easily installed an [RSS.chat](http://RSS.chat) server on my webhost at [RSS.storian.org](https://rss.storian.org) (whitelisted to me only for now). I wrote a first post and immediately subscribed to my feed in my installation of Feedland (Zuiker tab in my [News Product](https://news.mistersugar.com)). Will stop here for the night, satisfied.', NULL, NULL, NULL, NULL, NULL, '2026-07-28T01:22:41Z', '2026-07-28T01:22:41Z');
